DIV=V+[['拉丁语：dīvertere → dīversus','转开、分向不同方向 → 不同的']]
DIVERSE=DIV+[['古法语 divers → 英语 diverse','各不相同的；多种多样的']]
REVERT=V+[['拉丁语：revertere → reversus','转回、返回 → 已转回的']]
REV=REVERT+[['古法语 revers；后期拉丁语 reversāre → 古法语 reverser','形容词“相反的”和动词“翻转”的支线'],['英语：reverse','相反的；反面；使倒转']]
REVBOTH=REVERT+[['法语 réversible；英语 reverse + -ible','词典分别提出法语借入和英语内部派生的分析'],['英语：reversible','可反转、可恢复；两面能用']]
INV=V+[['拉丁语：invertere → inversus','翻转、颠倒 → 已倒转的']]
PER=V+[['拉丁语：pervertere → perversus','彻底翻倒、弄歪 → 乖离常理的']]
SUB=V+[['拉丁语：subvertere → subversus','从下面翻过来 → 推翻、破坏']]
CONTRA=V+[['拉丁语：contrōversus → contrōversia','朝相反方向 → 争论、争议']]
TRANS=V+[['拉丁语：trānsvertere → trānsversus','转向横边 → 横过的']]
VERTEX=V+[['拉丁语：vertex，词干 vertic-','旋转、旋涡；头顶、顶点']]
VERTEBRA=[['拉丁语：vertebra','关节、椎骨；通常认为与 vertere“转”有关']]
INTRO=[['拉丁语构件：intrō + vertere','向内 + 转'],['近代拉丁语、早期英语：向内转的词族','先用于转向内侧、思想向内等'],['20 世纪心理学：introvert / introversion','在荣格等人的用法中形成内向这一心理概念']]
EXTRA=[['拉丁语构件：extrā + vertere','向外 + 转'],['德语心理学：Extravert 等','把兴趣与注意力导向外部'],['英语：extravert → extrovert','心理学用语；后一拼写受 introvert 影响']]
